	@Test
	void simultaneousScopesOnOneStatisticsFacadeKeepTheirOwnSourceSelections(@TempDir Path root) throws Exception {
		try (Fixture fixture = new Fixture(root, false);
				var workers = Executors.newVirtualThreadPerTaskExecutor()) {
			LmdbEvaluationStatistics shared = (LmdbEvaluationStatistics) fixture.store.getBackingStore()
					.getEvaluationStatistics();
			CountDownLatch bothEntered = new CountDownLatch(2);
			var explicit = workers
					.submit(() -> concurrentRows(fixture, shared, FrontierLeafProbe.EXPLICIT, bothEntered));
			var inferred = workers
					.submit(() -> concurrentRows(fixture, shared, FrontierLeafProbe.INFERRED, bothEntered));
			assertEquals(2.0d, explicit.get(30, TimeUnit.SECONDS));
			assertEquals(1.0d, inferred.get(30, TimeUnit.SECONDS));
		}
	}

	private static double concurrentRows(Fixture fixture, LmdbEvaluationStatistics shared, int plane,
			CountDownLatch bothEntered) throws Exception {
		try (Read read = fixture.read(plane, shared, null)) {
			return read.entry(null, (prepared, cascades) -> {
				bothEntered.countDown();
				try {
					assertTrue(bothEntered.await(30, TimeUnit.SECONDS),
							"both actual worker entries reached their scopes");
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new AssertionError(interrupted);
				}
				var call = PackedCostTestSupport.preparedLeaf(prepared);
				try (var session = read.model().openSession(call.query())) {
					assertTrue(session instanceof LmdbFrontierStatisticsCostSession);
					return estimate(session, call).outputRows();
				}
			});
		}
	}

	@Test
	void naturalWarmAndDetachedRefreshRetainTheRuntimePlanePopulation(@TempDir Path root) throws Exception {
		try (Fixture fixture = new Fixture(root, true);
				var connection = fixture.repository.getConnection()) {
			Map<Boolean, TupleExpr> cold = new HashMap<>();
			Map<Boolean, TupleExpr> hot = new HashMap<>();
			for (boolean includeInferred : new boolean[] { false, true }) {
				cold.put(includeInferred, explained(connection, includeInferred));
				hot.put(includeInferred, explained(connection, includeInferred));
			}
			// A real committed data revision schedules the ordinary asynchronous cache refresh.
			for (SailRepository target : new SailRepository[] { fixture.repository, fixture.oracle }) {
				try (var writer = target.getConnection()) {
					writer.begin();
					writer.add(VF.createIRI("urn:population-owner:d"), RDF.TYPE, TYPE, G);
					((InferencerConnection) writer.getSailConnection()).addInferredStatement(
							VF.createIRI("urn:population-owner:e"), RDF.TYPE, TYPE, G);
					writer.commit();
				}
			}
			assertEquals(FrontierStatisticsAvailability.READY,
					fixture.store.rebuildFrontierStatistics().availability());
			Map<Boolean, TupleExpr> refreshed = new HashMap<>();
			for (boolean includeInferred : new boolean[] { false, true }) {
				explained(connection, includeInferred);
				refreshed.put(includeInferred, LmdbPlannerAwait.awaitDetachedPlanRefreshPlan(
						() -> explained(connection, includeInferred)));
			}
			org.junit.jupiter.api.Assertions.assertAll(
					() -> assertPlannedPopulation(cold.get(false), 2L, "cold explicit"),
					() -> assertPlannedPopulation(cold.get(true), 3L, "cold inclusive"),
					() -> assertPlannedPopulation(hot.get(false), 2L, "warm explicit"),
					() -> assertPlannedPopulation(hot.get(true), 3L, "warm inclusive"),
					() -> assertPlannedPopulation(refreshed.get(false), 3L, "refreshed explicit"),
					() -> assertPlannedPopulation(refreshed.get(true), 5L, "refreshed inclusive"),
					() -> assertTrue(Boolean
							.parseBoolean(hot.get(false).getStringMetricPlanned("optimizer.pipelinePlanCacheHit"))),
					() -> assertTrue(Boolean
							.parseBoolean(hot.get(true).getStringMetricPlanned("optimizer.pipelinePlanCacheHit"))),
					() -> assertEquals(3L,
							fixture.oracle(FrontierLeafProbe.EXPLICIT)
									.values()
									.stream()
									.mapToLong(Long::longValue)
									.sum()),
					() -> assertEquals(5L,
							fixture.oracle(FrontierLeafProbe.BOTH_PLANES)
									.values()
									.stream()
									.mapToLong(Long::longValue)
									.sum()));
		}
	}

	@Test
	void naturalSelectedDatasetRefreshUsePreservesExplicitAndBothPlaneBags(@TempDir Path root) throws Exception {
		IRI inferredDefault = VF.createIRI("urn:population-owner:inferred-default-refresh");
		IRI committedExplicit = VF.createIRI("urn:population-owner:committed-explicit-refresh");
		IRI committedInferred = VF.createIRI("urn:population-owner:committed-inferred-refresh");
		try (Fixture fixture = new Fixture(root, true)) {
			try (var writer = fixture.repository.getConnection()) {
				writer.begin();
				((InferencerConnection) writer.getSailConnection())
						.addInferredStatement(inferredDefault, RDF.TYPE, TYPE);
				writer.commit();
			}
			try (var writer = fixture.oracle.getConnection()) {
				writer.begin();
				((InferencerConnection) writer.getSailConnection())
						.addInferredStatement(inferredDefault, RDF.TYPE, TYPE);
				writer.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY,
					fixture.store.rebuildFrontierStatistics().availability());
			Dataset selected = physicalDefault();
			Map<Boolean, Map<Value, Long>> expectedBefore = Map.of(
					false, Map.of(A, 1L),
					true, Map.of(A, 1L, inferredDefault, 1L));
			Map<Boolean, TupleExpr> cold = new HashMap<>();
			Map<Boolean, TupleExpr> warm = new HashMap<>();
			try (var connection = fixture.repository.getConnection()) {
				for (boolean includeInferred : new boolean[] { false, true }) {
					assertEquals(expectedBefore.get(includeInferred),
							queryBag(fixture.oracle, QUERY, selected, includeInferred));
					cold.put(includeInferred, explained(connection, includeInferred, selected));
					warm.put(includeInferred, explained(connection, includeInferred, selected));
					assertEquals(expectedBefore.get(includeInferred),
							queryBag(fixture.repository, QUERY, selected, includeInferred));
				}
				for (SailRepository target : new SailRepository[] { fixture.repository, fixture.oracle }) {
					try (var writer = target.getConnection()) {
						writer.begin();
						writer.add(committedExplicit, RDF.TYPE, TYPE);
						((InferencerConnection) writer.getSailConnection())
								.addInferredStatement(committedInferred, RDF.TYPE, TYPE);
						writer.commit();
					}
				}
				long latestMutation = fixture.store.getBackingStore()
						.getTripleStore()
						.frontierMutationJournalState()
						.latestSequence();
				assertTrue(fixture.store.getBackingStore()
						.awaitFrontierStatisticsCoveredSequence(latestMutation,
								TimeUnit.SECONDS.toMillis(30)),
						"the real committed Frontier population must be covered before detached refresh is observed");
				for (boolean includeInferred : new boolean[] { false, true }) {
					TupleExpr refreshRequest = explained(connection, includeInferred, selected);
					TupleExpr used = LmdbPlannerAwait.awaitDetachedPlanRefreshPlan(
							() -> explained(connection, includeInferred, selected));
					Map<Value, Long> expectedAfter = includeInferred
							? Map.of(A, 1L, inferredDefault, 1L, committedExplicit, 1L, committedInferred, 1L)
							: Map.of(A, 1L, committedExplicit, 1L);
					assertEquals(expectedAfter, queryBag(fixture.oracle, QUERY, selected, includeInferred));
					assertEquals(expectedAfter, queryBag(fixture.repository, QUERY, selected, includeInferred));
					assertEquals("USE", used.getStringMetricPlanned("optimizer.planCacheLookupOutcome"),
							"the same selected-Dataset/plane must use its detached refresh\n" + used);
					System.out.println("selected Dataset refresh-use control includeInferred=" + includeInferred
							+ ": cold=" + planReceipt(cold.get(includeInferred))
							+ ", warm=" + planReceipt(warm.get(includeInferred))
							+ ", refreshRequest=" + planReceipt(refreshRequest)
							+ ", detachedUSE=" + planReceipt(used));
				}
			}
		}
	}

	private static TupleExpr explained(org.eclipse.rdf4j.repository.RepositoryConnection connection,
			boolean includeInferred) {
		var query = connection.prepareTupleQuery(QUERY);
		query.setIncludeInferred(includeInferred);
		return (TupleExpr) query.explain(Explanation.Level.Optimized).tupleExpr();
	}

	private static TupleExpr explained(org.eclipse.rdf4j.repository.RepositoryConnection connection,
			boolean includeInferred, Dataset dataset) {
		var query = connection.prepareTupleQuery(QUERY);
		query.setIncludeInferred(includeInferred);
		query.setDataset(dataset);
		return (TupleExpr) query.explain(Explanation.Level.Optimized).tupleExpr();
	}

	private static String planReceipt(TupleExpr plan) {
		StatementPattern leaf = firstPattern(plan);
		return "cacheHit=" + plan.getStringMetricPlanned("optimizer.pipelinePlanCacheHit")
				+ ", lookup=" + plan.getStringMetricPlanned("optimizer.planCacheLookupOutcome")
				+ ", leafSource=" + leaf.getStringMetricPlanned("plannedEstimateSource")
				+ ", leafRows=" + leaf.getDoubleMetricPlanned("plannedCardinalityRows");
	}

	private static void assertPlannedPopulation(TupleExpr plan, long rows, String label) {
		StatementPattern leaf = firstPattern(plan);
		assertEquals((double) rows, leaf.getDoubleMetricPlanned("plannedCardinalityRows"), label + '\n' + plan);
		assertTrue(leaf.getStringMetricPlanned("plannedEstimateSource").startsWith("frontier-v2"), label + '\n' + plan);
	}

	@Test
	void actualDetachedOwnerOpensEachRequestedPlaneAndClosesEveryOwner(@TempDir Path root) throws Exception {
		try (Fixture fixture = new Fixture(root, false)) {
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) fixture.store.getBackingStore()
					.getEvaluationStatistics();
			LmdbEstimatorRuntime runtime = statistics.estimatorRuntime();
			LmdbDetachedPlanningSnapshotProvider provider = (LmdbDetachedPlanningSnapshotProvider) statistics;
			assertThrows(IllegalArgumentException.class, () -> provider.openDetachedPlanningSnapshot(0));
			for (int mask : new int[] { FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.INFERRED,
					FrontierLeafProbe.BOTH_PLANES }) {
				SailDatasetTripleTermSource closedSource;
				java.util.List<LmdbPhysicalReadComposition.PlaneOccurrence> owners;
				try (var snapshot = provider.openDetachedPlanningSnapshot(mask);
						var pin = snapshot.pinPlanningReads(runtime);
						var scope = runtime.beginFrontierReadScope(snapshot.tripleSource(), null, mask)) {
					closedSource = snapshot.tripleSource();
					var composition = SailDatasetReadComposition
							.resolve(closedSource, LmdbPhysicalReadComposition.class,
									LmdbPhysicalReadComposition::union)
							.orElseThrow();
					owners = composition.planeOccurrences();
					assertEquals(mask, composition.frontierPlaneMask());
					assertEquals(mask, runtime.frontierReadPlaneMask());
					assertEquals(LmdbFrontierReadPopulation.STORE_DEFAULTS, runtime.frontierReadPopulation());
					for (var occurrence : owners) {
						assertSame(runtime.physicalTripleStore().borrowedPlanningTxn(),
								occurrence.owner().pinnedReadTxn().orElseThrow());
						assertSame(runtime.valueStore().borrowedPlanningSnapshot(),
								occurrence.owner().pinnedValueSnapshot().orElseThrow());
						assertTrue(occurrence.owner().isCurrentForPhysicalCost());
					}
					Map<Value, Long> bag = new HashMap<>();
					try (var statements = closedSource.getStatements(null, RDF.TYPE, TYPE)) {
						while (statements.hasNext()) {
							bag.merge(statements.next().getSubject(), 1L, Long::sum);
						}
					}
					assertEquals(fixture.oracle(mask), bag);
				}
				assertThrows(SailException.class, closedSource::getSnapshotEpoch);
				for (var occurrence : owners) {
					assertTrue(occurrence.owner().pinnedReadTxn().isEmpty());
					assertTrue(occurrence.owner().pinnedValueSnapshot().isEmpty());
				}
			}
			assertFalse(runtime.hasPairedPlanningAuthority());
		}
	}

	@Test
	void planeQualifiedKeysSeparateAllReadersAndRejectTheAmbiguousLegacyNamespace(@TempDir Path root)
			throws Exception {
		try (Fixture fixture = new Fixture(root, false)) {
			Map<Integer, String> logical = new HashMap<>();
			Map<Integer, String> physicalSources = new HashMap<>();
			for (int mask : new int[] { FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.INFERRED,
					FrontierLeafProbe.BOTH_PLANES }) {
				try (Read read = fixture.read(mask, null, null)) {
					read.entry(null, (prepared, cascades) -> {
						var call = PackedCostTestSupport.preparedLeaf(prepared);
						try (var memory = PackedCostTestSupport.providerMemory(
								new PackedPlannerLimits(1_000_000L, Long.MAX_VALUE, 32L * 1024L * 1024L));
								var session = read.model().openSession(call.query());
								var origins = new LmdbPhysicalEventOrigins(call.query(), true, mask)) {
							session.bindProviderMemory(memory);
							origins.bind(memory);
							PackedCostEstimate output = estimate(session, call);
							String key = output.plannedStringMetric("optimizer.frontierLogicalGroupKey");
							assertNotNull(key, "the actual owned selected leaf must expose its logical population key");
							logical.put(mask, key);
							String scope = LearningKeyCodec.decode(key.split("\\|", -1)[8]);
							assertEquals("store-defaults|DEFAULT_CONTEXTS|mapped-read-v2:planes:" + mask, scope);
							String[] legacyFields = key.split("\\|", -1);
							legacyFields[8] = LearningKeyCodec.encode("store-defaults|DEFAULT_CONTEXTS");
							org.junit.jupiter.api.Assertions.assertNotEquals(String.join("|", legacyFields), key,
									"no newly qualified plane may address an old plane-ambiguous logical cell");
							var origin = origins.complete(PhysicalEventKey.LEAF, call.relationId(), call.emptyContext(),
									output, false);
							assertNotNull(origin);
							physicalSources.put(mask, origin.source);
							String legacySource = call.query()
									.tryPhysicalSourceIdentity(memory, LearningKeyCodec.MAX_STRING_BYTES);
							assertEquals("mapped-read-v2:planes:" + mask + '|' + legacySource, origin.source);
							org.junit.jupiter.api.Assertions.assertNotEquals(legacySource, origin.source,
									"even BOTH must not address the old plane-ambiguous physical source");
						}
						return null;
					});
				}
			}
			assertEquals(3L, logical.values().stream().distinct().count());
			assertEquals(3L, physicalSources.values().stream().distinct().count());
		}
	}

