	@Test
	void naturalTelemetryRecordsQualifiedPlaneFeedbackIdentities(@TempDir Path root) throws Exception {
		try (Fixture fixture = new Fixture(root, true);
				var connection = fixture.repository.getConnection();
				Read explicit = fixture.read(FrontierLeafProbe.EXPLICIT, null, null);
				Read both = fixture.read(FrontierLeafProbe.BOTH_PLANES, null, null)) {
			Map<Value, Long> explicitOracle = fixture.oracle(FrontierLeafProbe.EXPLICIT);
			Map<Value, Long> bothOracle = fixture.oracle(FrontierLeafProbe.BOTH_PLANES);
			Map<Value, Long> explicitBag = explicit.subjectBag();
			Map<Value, Long> bothBag = both.subjectBag();
			assertEquals(explicitOracle, explicitBag, "real EXPLICIT reader population");
			assertEquals(bothOracle, bothBag, "real BOTH reader population");
			assertFalse(explicitBag.equals(bothBag), "the two physical read planes have independently different bags");
			long explicitRevision = snapshotRevision(explicit);
			long bothRevision = snapshotRevision(both);
			assertEquals(explicitRevision, bothRevision, "real read owners pin the same store revision");
			assertEquals(explicit.source.getSnapshotEpoch(), both.source.getSnapshotEpoch(),
					"real read owners expose the same durable snapshot epoch");

			TelemetryIdentityReceipt explicitIdentity = telemetryIdentityReceipt(fixture, connection, false);
			TelemetryIdentityReceipt bothIdentity = telemetryIdentityReceipt(fixture, connection, true);
			assertEquals(explicitIdentity.dataEpoch(), bothIdentity.dataEpoch(),
					"public Telemetry routes use the same store data epoch");
			assertEquals(explicitIdentity.queryBag(), explicitOracle, "public EXPLICIT query bag");
			assertEquals(bothIdentity.queryBag(), bothOracle, "public BOTH query bag");
			System.out.println("natural plane identity receipts at revision=" + explicitRevision + ": "
					+ explicitIdentity + " ; " + bothIdentity);
			org.junit.jupiter.api.Assertions.assertAll(
					() -> assertTrue(explicitIdentity.logicalAdmitted(), "EXPLICIT admits logical feedback"),
					() -> assertTrue(explicitIdentity.physicalAdmitted(), "EXPLICIT admits physical feedback"),
					() -> assertTrue(bothIdentity.logicalAdmitted(), "BOTH admits logical feedback"),
					() -> assertTrue(bothIdentity.physicalAdmitted(), "BOTH admits physical feedback"),
					() -> org.junit.jupiter.api.Assertions.assertNotEquals(explicitIdentity.logicalLookupIdentity(),
							bothIdentity.logicalLookupIdentity(),
							"complete logical lookup identity must distinguish the real plane populations"),
					() -> org.junit.jupiter.api.Assertions.assertNotEquals(explicitIdentity.physicalLookupIdentity(),
							bothIdentity.physicalLookupIdentity(),
							"complete physical lookup identity must distinguish the real plane populations"));
		}
	}

