	private record ExactPopulationReceipt(String expression, String graphDomain, boolean nativeGraphAllowed,
			long sourceEpoch, long borrowedEpoch, long planningRevision, double rawBothRows, String source,
			double factorRows, boolean factorExact, double bagRows, boolean bagExact, double lower, double upper) {
	}

	private static ExactPopulationReceipt exactPopulationReceipt(Read read, TupleExpr input, Dataset selected,
			EstimationTier tier) {
		return read.entry(input.clone(), selected, (prepared, cascades) -> {
			StatementPattern pattern = firstPattern(prepared);
			assertTrue(read.runtime.hasPairedPlanningAuthority(), "real query entry must borrow its actual pair");
			var borrowed = read.runtime.physicalTripleStore().borrowedPlanningTxn();
			assertNotNull(borrowed);
			var owner = read.source.getDataset().unwrap(LmdbPinnedReadTxnSource.class).orElseThrow();
			assertSame(owner.pinnedReadTxn().orElseThrow(), borrowed, "actual owning transaction object");
			assertSame(owner.pinnedValueSnapshot().orElseThrow(), read.runtime.valueStore().borrowedPlanningSnapshot(),
					"actual same-store dictionary owner, not just an epoch");
			long sourceEpoch = read.source.getSnapshotEpoch().orElseThrow();
			assertEquals(sourceEpoch, borrowed.nativeTransactionId(),
					"exact counter is read on the actual source snapshot");
			var cost = org.eclipse.rdf4j.query.algebra.evaluation.optimizer.JoinFactorCostModel.CostContext
					.of(Set.of(), 1.0d, 1.0d, false)
					.withEstimationTier(tier);
			var selectedCost = read.runtime.factorCost(pattern, cost).orElseThrow();
			BagEstimate bag = selectedCost.getBagEstimate().orElseThrow();
			// Diagnostic legacy call is deliberately not asserted equal to the query population.
			double rawBothRows = new LmdbStatementPatternCardinalitySource(read.runtime.valueStore(),
					read.runtime.physicalTripleStore()).estimateExact(pattern);
			return new ExactPopulationReceipt(pattern.toString(),
					org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PlanningGraphDomains.domain(pattern)
							.kind()
							.name(),
					LmdbPlanningGraphEvidence.allows(pattern), sourceEpoch, borrowed.nativeTransactionId(),
					read.runtime.physicalTripleStore().planningDataRevision(), rawBothRows, bag.source(),
					selectedCost.getOutputRows(), selectedCost.hasExactOutputRows(), bag.rows(), bag.isExact(),
					selectedCost.getNormalizedEstimateVector().lowerRows(),
					selectedCost.getNormalizedEstimateVector().upperRows());
		});
	}

	private static void assertExactPopulationCertificate(ExactPopulationReceipt receipt, long truth) {
		if (receipt.factorExact()) {
			assertEquals((double) truth, receipt.factorRows(),
					"complete factor certificate must describe actual population: " + receipt);
			assertTrue(receipt.lower() <= truth && truth <= receipt.upper(),
					"published bounds must contain actual rows: " + receipt);
		}
		if (receipt.bagExact()) {
			assertEquals((double) truth, receipt.bagRows(), "complete semantic bag certificate: " + receipt);
		}
		if (!receipt.nativeGraphAllowed()) {
			org.junit.jupiter.api.Assertions.assertNotEquals("lmdb-exact", receipt.source(),
					"active GRAPH/unknown domain cannot consume raw local dictionary/storage evidence: " + receipt);
		}
	}

	private static Map<Value, Long> exactPopulationBag(SailRepository repository, TupleExpr input, Dataset selected,
			boolean includeInferred) {
		Map<Value, Long> bag = new HashMap<>();
		try (var connection = repository.getConnection();
				var rows = connection.getSailConnection()
						.evaluate(input.clone(), selected, EmptyBindingSet.getInstance(), includeInferred)) {
			while (rows.hasNext()) {
				bag.merge(rows.next().getValue("s"), 1L, Long::sum);
			}
		}
		return bag;
	}

	private static String exactDatasetFields(Dataset selected) {
		return selected == null ? "null"
				: "explicit=" + selected.isExplicitReadDataset() + ";defaults="
						+ selected.getDefaultGraphResources() + ";named=" + selected.getNamedGraphResources();
	}

	private record LogicalLookupIdentity(LogicalLearningKey key, LearningApplicability applicability) {
	}

	private record PhysicalLookupIdentity(LogicalLearningKey logicalKey, PhysicalResidualKey physicalKey,
			LearningApplicability applicability) {
	}

	private record TelemetryIdentityReceipt(boolean includeInferred, Map<Value, Long> queryBag,
			boolean logicalAdmitted, boolean physicalAdmitted, int admissionFlags, long dataEpoch,
			String logicalKey, String logicalDigest, String applicability, String applicabilityDigest,
			String physicalSourceKey, String physicalSourceDigest, LogicalLookupIdentity logicalLookupIdentity,
			PhysicalLookupIdentity physicalLookupIdentity,
			double predictedRows, double predictedSourceRows) {
	}

	private static TelemetryIdentityReceipt telemetryIdentityReceipt(Fixture fixture,
			org.eclipse.rdf4j.repository.RepositoryConnection connection, boolean includeInferred) {
		var query = connection.prepareTupleQuery(QUERY);
		query.setIncludeInferred(includeInferred);
		var explanation = query.explain(Explanation.Level.Telemetry);
		StatementPattern pattern = firstPattern((TupleExpr) explanation.tupleExpr());
		var contract = pattern.getRuntimeFeedbackContract();
		assertNotNull(contract, "natural public Telemetry path exposes a contract: " + explanation);
		assertTrue(contract.descriptor() instanceof LmdbRuntimeFeedbackDescriptor,
				"natural public Telemetry path exposes the immutable mapped descriptor: " + explanation);
		var descriptor = (LmdbRuntimeFeedbackDescriptor) contract.descriptor();
		LogicalLearningKey logical = descriptor.logicalKey();
		PhysicalResidualKey physical = descriptor.physicalKey();
		LearningApplicability applicability = descriptor.applicability();
		assertEquals(logical, LogicalLearningKey.parse(logical.externalForm()), "logical key round trip");
		assertEquals(physical, PhysicalResidualKey.parse(physical.externalForm()), "physical source key round trip");
		assertEquals(applicability, LearningApplicability.parse(applicability.externalForm()),
				"complete applicability round trip");
		Map<Value, Long> actual = queryBag(fixture.repository, QUERY, null, includeInferred);
		return new TelemetryIdentityReceipt(includeInferred, actual,
				contract.admits(org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackContract.ADMIT_LOGICAL),
				contract.admits(org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackContract.ADMIT_PHYSICAL),
				contract.admissionFlags(), applicability.dataEpoch(), logical.externalForm(), logical.digest(),
				applicability.externalForm(), applicability.digest(), physical.externalForm(), physical.digest(),
				new LogicalLookupIdentity(logical, applicability),
				new PhysicalLookupIdentity(logical, physical, applicability), contract.rawPrediction().rows(),
				contract.rawPrediction().sourceRows());
	}

	private static long snapshotRevision(Read read) {
		var owner = read.source.getDataset()
				.unwrap(LmdbPinnedReadTxnSource.class)
				.orElseThrow(
						() -> new AssertionError("real read must expose its pinned transaction owner"));
		return owner.pinnedReadTxn()
				.orElseThrow(() -> new AssertionError("real read owner remains open"))
				.snapshotRevision();
	}

	@Test
	void actualNativeWorkAndFiniteValuesReceiptsKeepTheReaderPlane(@TempDir Path root) throws Exception {
		IRI predicate = VF.createIRI("urn:population-owner:work-p");
		String repeated = "SELECT ?s WHERE { ?s <" + predicate + "> ?s }";
		String finite = "SELECT ?s WHERE { VALUES ?s { <" + A + "> <" + B + "> } ?s <" + predicate + "> ?o }";
		try (Fixture fixture = new Fixture(root, true)) {
			for (SailRepository target : new SailRepository[] { fixture.repository, fixture.oracle }) {
				try (var writer = target.getConnection()) {
					writer.begin();
					writer.add(A, predicate, A);
					writer.add(B, predicate, C, G);
					var inferencer = (InferencerConnection) writer.getSailConnection();
					inferencer.addInferredStatement(C, predicate, C, G);
					inferencer.addInferredStatement(A, predicate, B, G);
					writer.commit();
				}
			}
			assertEquals(FrontierStatisticsAvailability.READY,
					fixture.store.rebuildFrontierStatistics().availability());
			for (int mask : new int[] { FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.BOTH_PLANES }) {
				try (Read read = fixture.read(mask, null, null)) {
					double nativePopulation = mask == FrontierLeafProbe.EXPLICIT ? 2.0d : 4.0d;
					double finiteRows = mask == FrontierLeafProbe.EXPLICIT ? 2.0d : 3.0d;
					assertEquals((long) nativePopulation, sourceRows(read, null, predicate));
					assertEquals((long) finiteRows, sourceRows(read, A, predicate) + sourceRows(read, B, predicate));
					assertEquals(queryBag(fixture.oracle, repeated, null, mask == FrontierLeafProbe.BOTH_PLANES),
							queryBag(fixture.repository, repeated, null, mask == FrontierLeafProbe.BOTH_PLANES));
					assertEquals(queryBag(fixture.oracle, finite, null, mask == FrontierLeafProbe.BOTH_PLANES),
							queryBag(fixture.repository, finite, null, mask == FrontierLeafProbe.BOTH_PLANES));
					try (var view = read.runtime.statisticsService().openCurrentView()) {
						var population = new FrontierLeafProbe(mask, FrontierLeafProbe.PREDICATE, 0L,
								read.runtime.valueStore().getId(predicate), 0L, 0L);
						assertEquals(nativePopulation, view.estimateLeaf(population).pointRows(),
								"independent exact physical-prefix table");
						for (Resource subject : new Resource[] { A, B }) {
							var lookup = new FrontierLeafProbe(mask,
									FrontierLeafProbe.SUBJECT | FrontierLeafProbe.PREDICATE,
									read.runtime.valueStore().getId(subject),
									read.runtime.valueStore().getId(predicate), 0L, 0L);
							assertEquals((double) sourceRows(read, subject, predicate),
									view.estimateLeaf(lookup).pointRows(),
									"independent finite lookup table precondition");
						}
					}
					for (boolean mappedProgram : new boolean[] { false, true }) {
						read.entry(repeated, null, (prepared, cascades) -> {
							var call = PackedCostTestSupport.preparedLeaf(prepared);
							try (var session = new LmdbPackedCostModel(read.runtime, read.source.getSnapshotEpoch(),
									true,
									read.source, read.strategy, mappedProgram).openSession(call.query())) {
								var work = estimate(session, call);
								assertEquals("native-prefix-before-equality",
										work.plannedStringMetric("optimizer.nativeAccessPopulation"));
								assertEquals(nativePopulation, work.accessRows(),
										"real provider work receipt before equality");
								assertEquals(nativePopulation, work.sequentialRows());
							}
							return null;
						});
						read.entry(finite, null, (prepared, cascades) -> {
							var call = PackedCostTestSupport.preparedFinite(prepared);
							try (var session = new LmdbPackedCostModel(read.runtime, read.source.getSnapshotEpoch(),
									true,
									read.source, read.strategy, mappedProgram).openSession(call.query())) {
								PackedCostEstimate work = new PackedCostEstimate();
								session.appendFactor(call.relationId(), call.prefixContext(), work);
								assertEquals(finiteRows, work.outputRows(), "finite VALUES candidate population");
								assertEquals(finiteRows, work.sequentialRows(),
										"finite VALUES candidate physical row visits");
							}
							return null;
						});
					}
					try (var connection = fixture.repository.getConnection()) {
						var query = connection.prepareTupleQuery(repeated);
						query.setIncludeInferred(mask == FrontierLeafProbe.BOTH_PLANES);
						String telemetry = query.explain(Explanation.Level.Telemetry).toString();
						int end = telemetry.indexOf("\n\nQuery explanation");
						String physical = end < 0 ? telemetry : telemetry.substring(0, end);
						var visits = java.util.regex.Pattern.compile("(?m)^\\s+rowsScannedActual: (\\d+)\\s*$")
								.matcher(physical);
						long scanned = 0L;
						while (visits.find()) {
							scanned += Long.parseLong(visits.group(1));
						}
						assertEquals(nativePopulation, (double) scanned,
								"actual selected native source visits: " + telemetry);

					}
				}
			}
		}
	}

	@Test
	void unsupportedAndForeignRawWorkCannotCertifyThisStoresDefaultPopulation(@TempDir Path root) throws Exception {
		IRI predicate = VF.createIRI("urn:population-owner:foreign-only-work");
		String text = "SELECT ?s WHERE { ?s <" + predicate + "> ?s }";
		try (Fixture owner = new Fixture(root.resolve("owner"), true);
				Fixture other = new Fixture(root.resolve("other"), true)) {
			for (SailRepository target : new SailRepository[] { other.repository, other.oracle }) {
				try (var writer = target.getConnection()) {
					writer.add(A, predicate, A, G);
				}
			}
			assertEquals(FrontierStatisticsAvailability.READY, other.store.rebuildFrontierStatistics().availability());
			try (Read own = owner.read(FrontierLeafProbe.BOTH_PLANES, null, null);
					Read foreign = other.read(FrontierLeafProbe.BOTH_PLANES, null, null);
					Read wrong = new Read(owner, foreign.dataset, own.statistics, null)) {
				assertEquals(1L, sourceRows(wrong, null, predicate), "the foreign actual native prefix is nonempty");
				assertEquals(Map.of(A, 1L), queryBag(other.oracle, text, null));
				wrong.entry(text, null, (prepared, cascades) -> {
					var call = PackedCostTestSupport.preparedLeaf(prepared);
					try (var session = wrong.model().openSession(call.query())) {
						var work = estimate(session, call);
						assertEquals("unavailable", work.plannedStringMetric("optimizer.nativeAccessPopulation"));
						assertFalse(Double.isFinite(work.accessRows()),
								"foreign work cannot use this dictionary's missing-IRI zero");
					}
					return null;
				});
				own.entry(physicalDefault(), (prepared, cascades) -> {
					var call = PackedCostTestSupport.preparedLeaf(prepared);
					try (var session = own.model().openSession(call.query())) {
						assertFalse(session instanceof LmdbFrontierStatisticsCostSession,
								"selected Dataset must not recover an unrestricted Frontier program through raw work");
					}
					return null;
				});
			}
		}
	}

